<?php session_start();require 'conectare.php';$id=filter_input(INPUT_GET,'id_carte',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare('SELECT c.id_carte,c.titlu,c.descriere,c.pret,a.nume_autor FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_carte=?');$s->execute([$id]);$book=$s->fetch();if(!$book){http_response_code(404);exit('Carte inexistenta.');}$s=$pdo->prepare('SELECT nume_utilizator,adresa_email,comentariu FROM comentarii WHERE id_carte=? ORDER BY id_comentariu DESC');$s->execute([$id]);$comments=$s->fetchAll();include 'page_top.php';include 'meniu.php';$img="./coperti/$id.jpg";?><article class="detail-card"><div><?php if(file_exists($img)):?><img class="detail-cover" src="<?=h($img)?>" alt=""><?php else:?><div class="detail-placeholder"><?=h($book['titlu'])?></div><?php endif;?></div><div><div class="author">de <?=h($book['nume_autor'])?></div><h1><?=h($book['titlu'])?></h1><p><?=nl2br(h($book['descriere']))?></p><p class="price" style="font-size:22px"><?=number_format((float)$book['pret'],2,',','.')?> lei</p><form action="cos.php?actiune=adauga" method="post"><input type="hidden" name="id_carte" value="<?=$id?>"><input type="submit" value="Adaugă în coș"></form></div></article><div class="comments"><h2 class="section-title">Opiniile cititorilor</h2><?php if(!$comments):?><div class="empty">Nu există încă opinii. Poți fi primul cititor care lasă una.</div><?php endif;foreach($comments as $c):?><div class="comment"><strong><?=h($c['nume_utilizator'])?></strong><br><?=nl2br(h($c['comentariu']))?></div><?php endforeach;?><form class="comment-form" action="adauga_comentariu.php" method="post"><h3>Adaugă opinia ta</h3><div class="form-grid"><input name="nume_utilizator" placeholder="Nume" required><input type="email" name="adresa_email" placeholder="Email" required><textarea name="comentariu" placeholder="Ce părere ai despre carte?" required></textarea></div><input type="hidden" name="id_carte" value="<?=$id?>"><br><input type="submit" value="Publică opinia"></form></div><?php include 'page_bottom.php';?>
